<script setup lang="ts">
import{ref}from'vue';import{useI18n}from'vue-i18n';import{getTool}from'../registry';import{useToolProcessing}from'../useToolProcessing';import{convertTimestamp,formatTimestampConversions,parseTimestamp,type TimestampInputType}from'./timestamp'
const{t}=useI18n();const tool=getTool('soc-tools.timestamp');const input=ref('');const output=ref('');const error=ref('');const type=ref<TimestampInputType>('seconds');const copied=ref(false);function transform(){error.value='';copied.value=false;if(!input.value){output.value='';return}try{output.value=formatTimestampConversions(convertTimestamp(parseTimestamp(input.value,type.value)))}catch{output.value='';error.value=t('tools.timestamp.invalid')}}const{inputBytes,isOverLimit,schedule}=useToolProcessing({input,output,error,maxInputBytes:tool.recommendedMaxInputBytes,process:transform});function clear(){input.value='';output.value='';error.value='';copied.value=false}async function copyOutput(){if(output.value){await navigator.clipboard.writeText(output.value);copied.value=true}}
</script>
<template><section class="tool-page" aria-labelledby="tool-title"><header class="tool-heading"><span class="category">{{ t(`categories.${tool.category}`) }}</span><h1 id="tool-title">{{ t(tool.nameKey) }}</h1><p>{{ t(tool.descriptionKey) }}</p></header><div class="io-panel"><div class="terminal-titlebar"><span class="window-marks" aria-hidden="true"><i /><i /><i /></span><span>[ timestamp ]</span></div><div class="io-strip"><label class="select-control">{{ t('tools.timestamp.inputType') }}<select v-model="type" @change="schedule"><option value="seconds">{{ t('tools.timestamp.seconds') }}</option><option value="milliseconds">{{ t('tools.timestamp.milliseconds') }}</option><option value="filetime">{{ t('tools.timestamp.filetime') }}</option><option value="human">{{ t('tools.timestamp.human') }}</option></select></label><span class="byte-count">{{ inputBytes }} B</span><div class="strip-actions"><button class="icon-button" type="button" :disabled="!output" :aria-label="copied?t('common.copied'):t('common.copy')" @click="copyOutput"><svg aria-hidden="true" viewBox="0 0 24 24"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M15 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h3" /></svg></button><button class="icon-button" type="button" :aria-label="t('common.clear')" @click="clear"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14" /></svg></button></div></div><p class="notice" role="note">{{ t('tools.timestamp.limitation') }}</p><p v-if="isOverLimit" class="notice warning" role="alert">{{ t('common.inputTooLarge',{size:'4 KB'}) }}</p><div class="editor-grid"><div class="field"><label for="timestamp-input"><span>$</span> {{ t('common.input') }}</label><div class="terminal-editor input-editor"><span class="editor-prompt" aria-hidden="true">$</span><textarea id="timestamp-input" v-model="input" :class="{invalid:error}" :aria-invalid="Boolean(error)" :aria-describedby="error?'timestamp-error':undefined" :placeholder="t('tools.timestamp.placeholder')" spellcheck="false" @input="schedule" /></div></div><div class="field"><label for="timestamp-output"><span>&gt;</span> {{ t('common.output') }}</label><div class="terminal-editor"><span class="editor-prompt" aria-hidden="true">&gt;</span><textarea id="timestamp-output" :value="output" :placeholder="t('common.result')" readonly /></div></div></div><p v-if="error" id="timestamp-error" class="notice error" role="alert">{{ error }}</p></div></section></template>
